css:
.cb-hero {
  background: #0a0a0c;
  color: #ffffff;
  padding: 90px 20px;
  text-align: center;
}
.cb-hero-inner {
  max-width: 780px;
  margin: 0 auto;
}
.cb-badge {
  display: inline-block;
  background: rgba(99, 102, 241, 0.15);
  color: #818cf8;
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
}
.cb-hero-title {
  font-size: clamp(32px, 5vw, 52px);
  margin: 18px 0 14px;
  line-height: 1.15;
}
.cb-hero-desc {
  color: #94a3b8;
  font-size: 17px;
  margin-bottom: 28px;
}
.cb-hero-btn {
  display: inline-block;
  background: #4f46e5;
  color: #ffffff;
  padding: 13px 28px;
  border-radius: 10px;
  text-decoration: none;
  font-weight: 600;
}

.cb-pricing {
  padding: 60px 20px;
  display: flex;
  justify-content: center;
  background: #f8fafc;
}
.cb-pricing-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 32px;
  max-width: 340px;
  width: 100%;
  text-align: center;
}
.cb-price {
  font-size: 38px;
  font-weight: 800;
  color: #4f46e5;
  margin: 12px 0;
}
.cb-pricing-card ul {
  list-style: none;
  padding: 0;
  margin: 20px 0;
  color: #475569;
}
.cb-pricing-card li {
  padding: 6px 0;
}
.cb-price-btn {
  display: block;
  background: #0f172a;
  color: #ffffff;
  padding: 12px;
  border-radius: 10px;
  text-decoration: none;
  font-weight: 600;
}

.cb-cta {
  padding: 50px 20px;
}
.cb-cta-box {
  max-width: 820px;
  margin: 0 auto;
  background: #0f172a;
  color: #ffffff;
  padding: 44px;
  border-radius: 18px;
  text-align: center;
}
.cb-cta-btn {
  display: inline-block;
  margin-top: 18px;
  background: #84cc16;
  color: #0f172a;
  padding: 12px 26px;
  border-radius: 10px;
  font-weight: 700;
  text-decoration: none;
}
